AUDIT: SESSION,3,1,DDL,CREATE FUNCTION,FUNCTION,public.broadcast_consultant_changes(),"-- ═══════════════════════════════════════════════════════════════════════════════
-- §3. Recreate trg_broadcast_consultant
-- ═══════════════════════════════════════════════════════════════════════════════
-- Fires on every Consultant UPDATE. Two fanouts:
--   • sparkScore changed → `consultant:{uid}:sparks`
--   • status changed     → `admin:verification` + `user:{uid}:notifications`
-- All wrapped in EXCEPTION so a broadcast failure never blocks the DML.
-- ═══════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.broadcast_consultant_changes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $fn$
BEGIN
  BEGIN
    IF NEW.""sparkScore"" IS DISTINCT FROM OLD.""sparkScore"" THEN
      PERFORM realtime.broadcast_changes(
        'consultant:' || NEW.""userId""::text || ':sparks',
        TG_OP, TG_OP, TG_TABLE_NAME, TG_TABLE_SCHEMA, NEW, OLD
      );
    END IF;

    IF NEW.status IS DISTINCT FROM OLD.status THEN
      PERFORM realtime.broadcast_changes(
        'admin:verification',
        TG_OP, TG_OP, TG_TABLE_NAME, TG_TABLE_SCHEMA, NEW, OLD
      );
      PERFORM realtime.broadcast_changes(
        'user:' || NEW.""userId""::text || ':notifications',
        TG_OP, TG_OP, TG_TABLE_NAME, TG_TABLE_SCHEMA, NEW, OLD
      );
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'broadcast_consultant_changes: %', SQLERRM;
  END;

  RETURN NEW;
END;
$fn$",<not logged>

AUDIT: SESSION,2,1,DDL,CREATE FUNCTION,FUNCTION,public.billing_settle_v2(pg_catalog.uuid),"-- ═══════════════════════════════════════════════════════════════════════════════
-- §2. billing_settle_v2
-- ═══════════════════════════════════════════════════════════════════════════════
-- Atomic final settlement. Called when a session ends.
--   • Computes final cost from server clock
--   • Refunds unused escrow to the seeker (human sessions only)
--   • Credits the consultant earning (human sessions only)
--   • Broadcasts ENDED to `session:{id}`
-- ═══════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.billing_settle_v2(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_caller      uuid := auth.uid();
  v_sess        RECORD;
  v_elapsed     int;
  v_minutes     int;
  v_rate        numeric := 0;
  v_cost        numeric := 0;
  v_fee         numeric := 0;
  v_earning     numeric := 0;
  v_held        numeric := 0;
  v_refund      numeric := 0;
  v_consultant_user uuid;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT * INTO v_sess FROM public.""CallSession""
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'session_not_found');
  END IF;

  -- Authorization
  IF v_sess.""userId"" <> v_caller
     AND NOT public.auth_is_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.""Consultant"" c
       WHERE c.id = v_sess.""consultantId"" AND c.""userId"" = v_caller
     )
  THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  -- Already ended
  IF v_sess.status = 'ENDED' THEN
    RETURN jsonb_build_object(
      'success',          true,
      'alreadyEnded',     true,
      'durationSeconds',  v_sess.""durationSeconds"",
      'totalCost',        v_sess.amount
    );
  END IF;

  v_elapsed := EXTRACT(EPOCH FROM (now() - v_sess.""startTime""))::int;
  v_minutes := CEIL(v_elapsed / 60.0)::int;

  -- Rate lookup
  IF v_sess.""isAI"" AND v_sess.""aiConsultantId"" IS NOT NULL THEN
    SELECT ""perMinuteRate"" INTO v_rate FROM public.""AIConsultant""
    WHERE id = v_sess.""aiConsultantId"";
  ELSIF v_sess.""consultantId"" IS NOT NULL THEN
    SELECT ""perMinuteRate"" INTO v_rate FROM public.""Consultant""
    WHERE id = v_sess.""consultantId"";
  END IF;
  v_rate    := COALESCE(v_rate, 0);
  v_cost    := v_minutes * v_rate;
  v_fee     := v_cost * 0.10;
  v_earning := v_cost - v_fee;
  v_held    := COALESCE(v_sess.amount, 0);

  -- Unused escrow refund (human only)
  v_refund := GREATEST(0, v_held - v_cost);

  -- Mark session ENDED
  UPDATE public.""CallSession""
  SET status            = 'ENDED',
      ""endTime""         = now(),
      ""durationSeconds"" = v_elapsed,
      amount            = v_cost,
      ""updatedAt""       = now()
  WHERE id = p_session_id;

  -- Refund to seeker
  IF v_refund > 0 AND NOT v_sess.""isAI"" THEN
    PERFORM public.credit_funds_safe(
      v_sess.""userId""::text,
      v_refund,
      'Session refund — unused balance',
      'session-refund:' || p_session_id::text
    );
  END IF;

  -- Credit consultant
  IF NOT v_sess.""isAI"" AND v_earning > 0 AND v_sess.""consultantId"" IS NOT NULL THEN
    SELECT c.""userId"" INTO v_consultant_user
    FROM public.""Consultant"" c WHERE c.id = v_sess.""consultantId"";

    IF v_consultant_user IS NOT NULL THEN
      PERFORM public.credit_funds_safe(
        v_consultant_user::text,
        v_earning,
        'Session earning — ' || v_minutes || ' min',
        'session-earn:' || p_session_id::text
      );
    END IF;
  END IF;

  -- Broadcast
  BEGIN
    PERFORM realtime.broadcast_changes(
      'session:' || p_session_id::text,
      'ENDED', 'ENDED', 'CallSession', 'public',
      jsonb_build_object(
        'sessionId',       p_session_id,
        'durationSeconds', v_elapsed,
        'totalCost',       v_cost,
        'refunded',        v_refund
      ),
      NULL
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN jsonb_build_object(
    'success',           true,
    'durationSeconds',   v_elapsed,
    'minutes',           v_minutes,
    'rate',              v_rate,
    'totalCost',         v_cost,
    'platformFee',       v_fee,
    'consultantEarning', v_earning,
    'refunded',          v_refund
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'code', SQLSTATE);
END;
$fn$",<not logged>

AUDIT: SESSION,1,1,DDL,CREATE FUNCTION,FUNCTION,public.billing_heartbeat_v2(pg_catalog.uuid),"-- ═══════════════════════════════════════════════════════════════════════════════
-- §1. billing_heartbeat_v2
-- ═══════════════════════════════════════════════════════════════════════════════
-- Server-authoritative heartbeat. Called every 30 s by the client.
--   • Resolves rate from Consultant (human) or AIConsultant (AI)
--   • Computes elapsed from server clock — never trusts the client
--   • Broadcasts state to `session:{id}` for realtime UI sync
--   • Returns `terminate: true` when balance runs out or 4h cap reached
-- ═══════════════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.billing_heartbeat_v2(p_session_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $fn$
DECLARE
  v_caller       uuid := auth.uid();
  v_sess         RECORD;
  v_elapsed      int;
  v_minutes      int;
  v_rate         numeric := 0;
  v_wallet       RECORD;
  v_remaining    numeric := 0;
  v_minutes_left int := 0;
  v_terminate    boolean := false;
  v_reason       text;
BEGIN
  IF v_caller IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT * INTO v_sess FROM public.""CallSession""
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'session_not_found');
  END IF;

  -- Authorization: owner OR consultant OR admin
  IF v_sess.""userId"" <> v_caller
     AND NOT public.auth_is_admin()
     AND NOT EXISTS (
       SELECT 1 FROM public.""Consultant"" c
       WHERE c.id = v_sess.""consultantId"" AND c.""userId"" = v_caller
     )
  THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  -- Already ended
  IF v_sess.status = 'ENDED' THEN
    RETURN jsonb_build_object(
      'success', true, 'ended', true,
      'elapsedSeconds', v_sess.""durationSeconds"",
      'minutesBilled',  v_sess.""durationSeconds"" / 60,
      'cost',           v_sess.amount,
      'remaining',      0,
      'minutesLeft',    0,
      'terminate',      false
    );
  END IF;

  -- Rate lookup: AI or human
  IF v_sess.""isAI"" AND v_sess.""aiConsultantId"" IS NOT NULL THEN
    SELECT ""perMinuteRate"" INTO v_rate FROM public.""AIConsultant""
    WHERE id = v_sess.""aiConsultantId"";
  ELSIF v_sess.""consultantId"" IS NOT NULL THEN
    SELECT ""perMinuteRate"" INTO v_rate FROM public.""Consultant""
    WHERE id = v_sess.""consultantId"";
  END IF;
  v_rate := COALESCE(v_rate, 0);

  v_elapsed := EXTRACT(EPOCH FROM (now() - v_sess.""startTime""))::int;
  v_minutes := v_elapsed / 60;

  -- Hard cap: 4 hours
  IF v_elapsed > 4 * 3600 THEN
    v_terminate := true;
    v_reason := 'Maximum session duration reached (4 hours).';
  END IF;

  -- Wallet
  SELECT * INTO v_wallet FROM public.""Wallet""
  WHERE ""userId"" = v_sess.""userId"" FOR UPDATE;

  IF FOUND THEN
    v_remaining := COALESCE(v_wallet.balance, 0) + COALESCE(v_wallet.escrow, 0);
    IF v_rate > 0 THEN
      v_minutes_left := FLOOR(v_remaining / v_rate)::int;
      IF v_minutes_left <= 0 THEN
        v_terminate := true;
        v_reason := COALESCE(v_reason, 'Insufficient balance.');
      END IF;
    ELSE
      v_minutes_left := 999;
    END IF;
  END IF;

  -- Broadcast (best-effort — never block the heartbeat)
  BEGIN
    PERFORM realtime.broadcast_changes(
      'session:' || p_session_id::text,
      'HEARTBEAT', 'HEARTBEAT', 'CallSession', 'public',
      jsonb_build_object(
        'sessionId',      p_session_id,
        'elapsedSeconds', v_elapsed,
        'minutesBilled',  v_minutes,
        'rate',           v_rate,
        'remaining',      v_remaining,
        'minutesLeft',    v_minutes_left,
        'terminate',      v_terminate
      ),
      NULL
    );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'billing_heartbeat_v2 broadcast failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object(
    'success',       true,
    'ended',         false,
    'elapsedSeconds', v_elapsed,
    'minutesBilled',  v_minutes,
    'rate',           v_rate,
    'cost',           v_minutes * v_rate,
    'remaining',      v_remaining,
    'minutesLeft',    v_minutes_left,
    'terminate',      v_terminate,
    'reason',         v_reason
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'code', SQLSTATE);
END;
$fn$",<not logged>

